import node_fs from "node:fs";
import node_path from "node:path";
import { fileURLToPath } from "node:url";
import selfsigned from "selfsigned";
const util_dirname = node_path.dirname(fileURLToPath(import.meta.url));
async function ensureDir(dir) {
    try {
        await node_fs.promises.access(dir);
    } catch  {
        await ensureDir(node_path.dirname(dir));
        await node_fs.promises.mkdir(dir);
    }
}
const resolveHttpsConfig = async (config, options)=>{
    const { key, cert } = config ?? {};
    if (key && cert) return {
        key,
        cert
    };
    const certPath = node_path.join(options.outputPath ?? util_dirname, options.filename ?? 'fake-cert.pem');
    const selfsignedOptions = {
        days: 30,
        keySize: 2048,
        ...options.selfsignedOptions
    };
    if (node_fs.existsSync(certPath)) {
        const stats = await node_fs.promises.stat(certPath);
        const timeDiff = Date.now() - stats.mtimeMs;
        const daysDiff = timeDiff / 86400000;
        if (daysDiff < selfsignedOptions.days) {
            const content = await node_fs.promises.readFile(certPath, {
                encoding: 'utf-8'
            });
            return {
                key: content,
                cert: content
            };
        }
    }
    const pem = selfsigned.generate(options.selfsignedAttrs ?? [
        {
            name: 'commonName',
            value: 'localhost'
        }
    ], selfsignedOptions);
    const content = pem.private + pem.cert;
    if (options.outputPath) await ensureDir(options.outputPath);
    await node_fs.promises.writeFile(certPath, content, {
        encoding: 'utf-8'
    });
    return {
        key: content,
        cert: content
    };
};
const PLUGIN_BASIC_SSL_NAME = 'rsbuild:basic-ssl';
const pluginBasicSsl = (options = {})=>({
        name: PLUGIN_BASIC_SSL_NAME,
        setup (api) {
            api.modifyRsbuildConfig(async (config)=>{
                const httpsConfig = await resolveHttpsConfig(config.server?.https, options);
                config.server = {
                    ...config.server,
                    https: httpsConfig
                };
            });
        }
    });
export { PLUGIN_BASIC_SSL_NAME, pluginBasicSsl };
